 private void player(){if(preview){notice("DEMO · fără redare audio");return;}startActivity(new Intent(this,source==1?FmActivity.class:MediaActivity.class).putExtra("now",true));}
 private void toggle(){if(preview){previewPlaying=!previewPlaying;face.invalidate();return;}if(source==1){if(FmService.playing||FmService.starting)stopService(new Intent(this,FmService.class));else player();}else if(PlaybackService.instance!=null)PlaybackService.instance.toggle();else player();face.invalidate();}
 private void previous(boolean next){if(preview){notice("DEMO · fără redare audio");return;}if(source==1){if(FmService.instance!=null&&FmService.playing)FmService.instance.seek(next);else notice("Pornește radioul din player");}else if(PlaybackService.instance!=null)PlaybackService.instance.next(next);else notice("Alege o piesă din bibliotecă");face.invalidate();}
 private void volume(int direction){if(preview){previewVolume=Math.max(0,Math.min(10,previewVolume+direction));face.invalidate();return;}if(source==1){if(FmService.instance!=null)FmService.instance.setVolume(FmService.volume+direction*2);else notice("Pornește radioul pentru volum FM");}else ((AudioManager)getSystemService(AUDIO_SERVICE)).adjustStreamVolume(AudioManager.STREAM_MUSIC,direction,0);face.invalidate();}
 private void menu(){options("Media curentă",new String[]{"Deschide playerul",source==0?"Sursă · Radio FM":"Sursă · Muzică","Piesa / postul anterior","Piesa / postul următor","Oprește sursa","Ajutor taste"},new Choice(){public void pick(int i){if(i==0)player();else if(i==1){source=1-source;face.invalidate();}else if(i==2||i==3)previous(i==3);else if(i==4){if(preview){previewPlaying=false;face.invalidate();return;}stopService(new Intent(NowPlayingActivity.this,source==1?FmService.class:PlaybackService.class));face.invalidate();}else options("Taste media",new String[]{"OK / 5: pauză sau oprire FM","← / → sau 4 / 6: anterior / următor","↑ / ↓: volum","*: schimbă sursa Muzică / FM","#: deschide playerul sursei"},new Choice(){public void pick(int n){}});}});}
 public boolean onKeyDown(int key,KeyEvent e){if(key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN){volume(key==KeyEvent.KEYCODE_DPAD_UP?1:-1);return true;}if(e.getRepeatCount()>0)return key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT||key==KeyEvent.KEYCODE_4||key==KeyEvent.KEYCODE_5||key==KeyEvent.KEYCODE_6||key==KeyEvent.KEYCODE_STAR||key==KeyEvent.KEYCODE_POUND||key==KeyEvent.KEYCODE_MENU||key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER||super.onKeyDown(key,e);if(key==KeyEvent.KEYCODE_MENU){menu();return true;}if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER||key==KeyEvent.KEYCODE_5){toggle();return true;}if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT||key==KeyEvent.KEYCODE_4||key==KeyEvent.KEYCODE_6){previous(key==KeyEvent.KEYCODE_DPAD_RIGHT||key==KeyEvent.KEYCODE_6);return true;}if(key==KeyEvent.KEYCODE_STAR){source=1-source;face.invalidate();return true;}if(key==KeyEvent.KEYCODE_POUND){player();return true;}return super.onKeyDown(key,e);}
