   for(int i=0;i<2;i++){box(c,12+i*112,48,116+i*112,70,i==source?palette.selection:palette.card);text(c,i==0?"MUZICĂ":"RADIO FM",23+i*112,63,12,i==source?palette.ink:Color.WHITE,84);}PlaybackService music=PlaybackService.instance;boolean active=preview?previewPlaying:source==1?FmService.playing:music!=null&&music.playing();String title=preview?(source==1?"LEO FM":"Lumini de seară"):source==1?(FmService.stationName.isEmpty()?"Radio FM":FmService.stationName):(PlaybackService.title.isEmpty()?"Nicio piesă aleasă":PlaybackService.title);String state=preview?"DEMO · fără redare":source==1?FmService.state:PlaybackService.state;box(c,12,79,228,166,palette.card);Bitmap cover=!preview&&source==0&&music!=null?music.cover():null;
