   int position=preview?85000:music==null?0:music.position(),duration=preview?233000:music==null?0:music.duration();text(c,state,14,185,13,palette.accent,212);box(c,14,195,226,200,0x445f6b7d);if(source==0){box(c,14,195,14+212*(duration>0?Math.min(1,position/(float)duration):0),200,palette.accent);text(c,MediaActivity.format(position)+" / "+MediaActivity.format(duration),14,216,12,Color.WHITE,150);}else text(c,preview?"Semnal · demonstrație":FmService.scanning?"Scanare în curs":FmService.seeking?"Caută postul…":FmService.signal<= -128?"Semnal indisponibil":"Semnal · "+FmService.signal+" dBm",14,216,12,Color.WHITE,170);
